const body = ($input.item && $input.item.json) ? ($input.item.json.body || $input.item.json) : {};
const input = body.input || body || {};
const email = (input.email || input.query || 'sarah@example.com').toLowerCase().trim();
const orderId = input.orderId || null;

const crmRecords = [
  {
    customerId: 'cust_98231',
    name: 'Sarah Connor',
    email: 'sarah@example.com',
    tier: 'BUSINESS',
    vipStatus: true,
    lifetimeValue: 2450,
    accountAgeDays: 420
  },
  {
    customerId: 'cust_44120',
    name: 'Alex Vance',
    email: 'alex@example.com',
    tier: 'PRO',
    vipStatus: false,
    lifetimeValue: 620,
    accountAgeDays: 180
  }
];

const customer = crmRecords.find(c => c.email === email || c.name.toLowerCase().includes(email)) || crmRecords[0];

return { customer, inputOrderId: orderId };

const prev = ($input.item && $input.item.json) ? $input.item.json : {};
const customer = prev.customer || { customerId: 'cust_98231', name: 'Sarah Connor', tier: 'BUSINESS', vipStatus: true };
const inputOrderId = prev.inputOrderId;

const ordersDatabase = {
  'cust_98231': [
    {
      orderId: 'ORD-9821',
      date: '2026-08-14T10:30:00Z',
      status: 'OUT_FOR_DELIVERY',
      carrier: 'DHL Express',
      trackingNumber: 'DHL-98421098',
      estimatedDelivery: 'Today by 5:00 PM',
      items: [
        { item: 'Ergonomic AI Workspace Hub', qty: 1, price: 499 },
        { item: 'Ultra-Fast USB-C Cable Pack', qty: 2, price: 45 }
      ],
      total: 544
    }
  ],
  'cust_44120': [
    {
      orderId: 'ORD-6542',
      date: '2026-08-10T14:00:00Z',
      status: 'DELIVERED',
      carrier: 'FedEx',
      trackingNumber: 'FDX-5512998',
      estimatedDelivery: 'Delivered on Aug 12',
      items: [
        { item: 'Smart Studio Microphone', qty: 1, price: 189 }
      ],
      total: 189
    }
  ]
};

const customerOrders = ordersDatabase[customer.customerId] || [];
const selectedOrder = inputOrderId 
  ? customerOrders.find(o => o.orderId === inputOrderId) || customerOrders[0]
  : customerOrders[0];

return { customer, activeOrder: selectedOrder };

const prev = ($input.item && $input.item.json) ? $input.item.json : {};
const customer = prev.customer || { tier: 'BUSINESS', vipStatus: true };
const activeOrder = prev.activeOrder;

const returnWindowDays = customer.tier === 'BUSINESS' ? 60 : 30;
const orderDate = activeOrder ? new Date(activeOrder.date) : new Date();
const diffDays = Math.floor((Date.now() - orderDate.getTime()) / (1000 * 60 * 60 * 24));
const isEligibleForReturn = diffDays <= returnWindowDays;

const returnPolicyDetails = {
  tier: customer.tier,
  maxReturnWindowDays: returnWindowDays,
  daysSincePurchase: diffDays,
  eligibleForReturn: isEligibleForReturn,
  freeReturnShipping: customer.vipStatus || customer.tier === 'BUSINESS',
  requiresManagerApproval: !isEligibleForReturn && customer.vipStatus
};

return {
  success: true,
  data: {
    customer: {
      customerId: customer.customerId,
      name: customer.name,
      email: customer.email,
      tier: customer.tier,
      vipStatus: customer.vipStatus
    },
    activeOrder: activeOrder || null,
    returnPolicy: returnPolicyDetails,
    workflowExecutionTime: new Date().toISOString()
  }
};
